function projectKey(address){return clean(address).toLowerCase()}
$('#createProject').onclick=async()=>{if(!selected.strom)return;$('#createProject').disabled=true;$('#stromStatus').textContent='Analyse Climacy / OFEN de la toiture…';const projects=getProjects(),key=projectKey(selected.strom.label);let p=projects.find(x=>x.key===key);try{const analysis=await analyseRoofAt(selected.strom),metrics=roofMetrics(analysis);if(!p){p={id:'P'+Date.now(),key,address:selected.strom.label,createdAt:new Date().toISOString(),trades:{}};projects.push(p)}p.roofMetrics=metrics;p.roofGeometry=serializeRoofs(analysis.roofs);p.buildingInfo={storeys:num(attr(analysis.gwrAttributes||{},['GASTW','gastw'])),groundArea:num(attr(analysis.gwrAttributes||{},['GAREA','garea'])),volume:num(attr(analysis.gwrAttributes||{},['GVOL','gvol'])),year:attr(analysis.gwrAttributes||{},['GBAUJ','gbauj'])||null};p.roofAnalysisStatus=analysis.status;p.addressPoint={x:selected.strom.x,y:selected.strom.y};if(!p.roofCheck)p.roofCheck={disabledPans:[],obstacles:[],validated:false};putProjects(projects);currentProject=p;$('#stromStatus').textContent=analysis.status==='complete'?`✓ Toiture trouvée : ${metrics.roofCount} pan(s), ${metrics.area} m². Vérification visuelle à effectuer.`:'Adresse trouvée, mais aucune surface OFEN exploitable.';setTimeout(()=>analysis.status==='complete'?openRoofCheck():openStromProject(),350)}catch(e){if(!p){p={id:'P'+Date.now(),key,address:selected.strom.label,createdAt:new Date().toISOString(),trades:{}};projects.push(p);putProjects(projects)}currentProject=p;$('#stromStatus').textContent='Projet créé. Analyse automatique indisponible : les métrés restent manuels.';setTimeout(openStromProject,500)}finally{$('#createProject').disabled=false}};
function renderSavedProjects(){const box=$('#savedProjects'),ps=getProjects();box.innerHTML=ps.length?`<h2>Projets préparés</h2><div class="project-list">${ps.map(p=>`<button class="project-item" data-id="${p.id}"><span>${p.address}</span><small>${Object.values(p.trades||{}).filter(x=>x.published).length} poste(s) publié(s)</small></button>`).join('')}</div>`:'<div class="empty-state">Aucun projet enregistré sur cet appareil pour le moment.</div>';box.querySelectorAll('.project-item').forEach(b=>b.onclick=()=>{currentProject=ps.find(p=>p.id===b.dataset.id);openStromProject()})}
function openStromProject(){if(!currentProject)return;$('#stromProjectTitle').textContent=currentProject.address;const m=currentProject.roofMetrics,c=currentProject.roofCheck;$('#stromProjectMeta').textContent=m?`Toiture : ${m.area} m² bruts · ${c?.validated?c.netArea+' m² nets validés':'vérification à effectuer'} · ${m.roofCount} pan(s)${m.egid?' · EGID '+m.egid:''}`:'Préparez les quantités avant de rendre un poste accessible aux entreprises.';$('#openRoofCheck').style.display=currentProject.roofGeometry?.length?'inline-block':'none';const g=$('#stromTradeGrid');g.innerHTML='';Object.entries(trades).forEach(([key,t])=>{const state=currentProject.trades?.[key];const b=document.createElement('button');b.className='trade';b.innerHTML=`<div class="icon">${t.icon}</div><b>${t.name}</b><p>${state?.published?'✓ Disponible aux entreprises':state?'Brouillon enregistré':key==='ferblanterie'&&c?.validated?'⚡ Métrage toiture validé':'À préparer'}</p>`;b.onclick=()=>openMeasure(key);g.appendChild(b)});show('stromProject')}
