$('#togglePanMode').onclick=()=>{roofMode='pan';obstaclePoints=[];$('#togglePanMode').classList.add('active-tool');$('#addObstacleMode').classList.remove('active-tool');$('#obstacleEditor').classList.add('hidden');$('#roofHelp').textContent='Cliquez sur un pan pour l’inclure ou l’exclure du métrage.';renderRoofEditor()};$('#addObstacleMode').onclick=()=>{roofMode='obstacle';obstaclePoints=[];$('#addObstacleMode').classList.add('active-tool');$('#togglePanMode').classList.remove('active-tool');$('#obstacleEditor').classList.remove('hidden');$('#roofHelp').textContent='Cliquez sur les 4 coins de l’obstacle dans l’ordre. Le polygone sera créé automatiquement au 4e point.';renderRoofEditor()};
