function renderCatalogPicker(data){let wrap=$('#measureCatalogPicker');if(!wrap){wrap=document.createElement('div');wrap.id='measureCatalogPicker';wrap.className='catalog-picker';$('#addMeasureRow').insertAdjacentElement('beforebegin',wrap)}const choices=catalogChoices(data);wrap.innerHTML=`<div><strong>Ajouter un paramètre existant</strong><small>Les paramètres retirés restent disponibles ici.</small></div><select id="catalogSelect"><option value="">Choisir dans la liste…</option>${choices.map((x,i)=>`<option value="${i}">${x.section} — ${x.label}</option>`).join('')}</select><button type="button" class="secondary" id="addCatalogParam" ${choices.length?'':'disabled'}>Ajouter</button>`;const b=$('#addCatalogParam');if(b)b.onclick=()=>{const i=Number($('#catalogSelect').value);if(!Number.isInteger(i)||!choices[i])return;const x=choices[i],rows=collectMeasure();rows.push({section:x.section||'Prestations complémentaires',label:x.label,qty:'',unit:x.unit||'pce',auto:false,qtyUnlocked:false});if(measureTrade==='ferblanterie'){const recalculated=applyAutoFerblanterie(rows,currentProject.roofMetrics,currentProject.roofCheck||null),restored=recalculated.find(r=>r.label===x.label&&r.section===x.section);if(restored){rows[rows.length-1]={...restored,qtyUnlocked:false}}}renderMeasure(rows)}}
function collectMeasure(){return[...$('#measureRows').children].reduce((a,el)=>{if(!el.classList.contains('measure-row'))return a;const previous=[...el.parentNode.children].slice(0,[...el.parentNode.children].indexOf(el)).reverse().find(x=>x.classList.contains('section-title'));a.push({section:previous?.textContent||'Prestations',label:el.querySelector('.measure-label').value.trim(),qty:el.querySelector('.measure-qty').value,unit:el.querySelector('.measure-unit').value,auto:el.dataset.auto==='1',autoSource:el.dataset.source||'',qtyUnlocked:el.dataset.qtyUnlocked==='1'});return a},[]).filter(r=>r.label)}
$('#measureRows').onclick=e=>{if(e.target.classList.contains('remove-line')){const rows=collectMeasure(),r=e.target.closest('.measure-row'),i=[...$('#measureRows').querySelectorAll('.measure-row')].indexOf(r);rememberTradeCatalog(rows);r.remove();renderCatalogPicker(collectMeasure());return}const toggle=e.target.closest('.qty-lock-toggle');if(toggle){const r=toggle.closest('.measure-row'),unlock=r.dataset.qtyUnlocked!=='1';r.dataset.qtyUnlocked=unlock?'1':'0';r.classList.toggle('qty-open',unlock);r.classList.toggle('qty-locked',!unlock);toggle.classList.toggle('is-open',unlock);toggle.classList.toggle('is-locked',!unlock);toggle.querySelector('.lock-symbol').textContent=unlock?'✓':'🔒';toggle.querySelector('.lock-text').textContent=unlock?'Modifiable':'Verrouillé';toggle.title=unlock?'Le prestataire peut modifier cette quantité':'Quantité verrouillée par Ström';return}if(e.target.classList.contains('lock-all-qty')||e.target.classList.contains('unlock-all-qty')){const unlock=e.target.classList.contains('unlock-all-qty');$('#measureRows').querySelectorAll('.measure-row').forEach(r=>{r.dataset.qtyUnlocked=unlock?'1':'0';r.classList.toggle('qty-open',unlock);r.classList.toggle('qty-locked',!unlock);const b=r.querySelector('.qty-lock-toggle');if(b){b.classList.toggle('is-open',unlock);b.classList.toggle('is-locked',!unlock);b.querySelector('.lock-symbol').textContent=unlock?'✓':'🔒';b.querySelector('.lock-text').textContent=unlock?'Modifiable':'Verrouillé'}})}};
$('#addMeasureRow').onclick=()=>{const data=collectMeasure(),label=prompt('Nom du nouveau paramètre :');if(!label?.trim())return;const unit=prompt('Unité (pce, m, m², bloc, forfait, h, kg) :','pce')||'pce';data.push({section:'Prestations complémentaires',label:label.trim(),qty:'',unit,auto:false,qtyUnlocked:false});rememberTradeCatalog(data);renderMeasure(data)};
function persistMeasure(rows,published){rememberTradeCatalog(rows);const ps=getProjects(),p=ps.find(x=>x.id===currentProject.id);p.trades[measureTrade]={rows,published,updatedAt:new Date().toISOString()};putProjects(ps);currentProject=p;$('#measureStatus').textContent=published?'✓ Bordereau validé. Seules les lignes renseignées seront visibles par l’entreprise.':'✓ Brouillon enregistré.';if(published)setTimeout(openStromProject,650)}function missingSummary(rows){const missing=rows.filter(r=>r.qty===''||num(r.qty)===null),sections=[...new Set(missing.map(r=>r.section))];return{missing,sections}}function openIncompleteModal(rows){pendingPublishRows=rows;const {missing,sections}=missingSummary(rows);$('#incompleteList').innerHTML=`<div class="warning-count"><strong>${missing.length}</strong> ligne(s) non renseignée(s)</div>${sections.map(s=>{const n=missing.filter(r=>r.section===s).length;return`<div class="missing-section"><span>${s}</span><b>${n} ligne${n>1?'s':''}</b></div>`}).join('')}`;$('#incompleteModal').classList.add('open');$('#incompleteModal').setAttribute('aria-hidden','false')}function closeIncompleteModal(){pendingPublishRows=null;$('#incompleteModal').classList.remove('open');$('#incompleteModal').setAttribute('aria-hidden','true')}$('#saveDraft').onclick=()=>persistMeasure(collectMeasure(),false);$('#publishMeasure').onclick=()=>{const rows=collectMeasure(),{missing}=missingSummary(rows);if(missing.length){openIncompleteModal(rows);return}persistMeasure(rows,true)};$('#modalEdit').onclick=closeIncompleteModal;$('#modalContinue').onclick=()=>{const rows=pendingPublishRows;closeIncompleteModal();persistMeasure(rows,true)};$('#incompleteModal').onclick=e=>{if(e.target===$('#incompleteModal'))closeIncompleteModal()};
$('#companyFind').onclick=()=>{if(!selected.company||!companyTrade)return;const p=getProjects().find(x=>x.key===projectKey(selected.company.label)),state=p?.trades?.[companyTrade];if(!p||!state?.published){$('#companyStatus').textContent=`Aucun bordereau ${trades[companyTrade].name} n’est encore disponible pour cette adresse.`;return}currentProject=p;openCompanyQuote(state)};function activeRows(state){return(state.rows||[]).filter(r=>r.qty!==''&&num(r.qty)!==null)}function companyRowQty(r){const input=r.querySelector('.company-qty');return input?input.value:r.querySelector('.locked-qty')?.textContent.replace('🔒','').trim()||''}
function openCompanyQuote(state){$('#companyProjectTitle').textContent=trades[companyTrade].name;$('#companyProjectMeta').textContent=currentProject.address;const box=$('#companyRows');box.innerHTML='';let last='';const visible=activeRows(state);visible.forEach((r,i)=>{if(r.section!==last){const h=document.createElement('div');h.className='section-title';h.textContent=r.section;box.appendChild(h);last=r.section}const d=document.createElement('div');d.className='row';d.dataset.i=i;d.innerHTML=`<div class="designation">${r.label}</div>${r.qtyUnlocked===true?`<div class="editable-qty"><span title="Quantité modifiable par le prestataire">🔓</span> <input class="company-qty" type="number" min="0" step="0.01" value="${r.qty}"></div>`:`<div class="locked-qty">🔒 ${r.qty}</div>`}<div class="locked-unit">🔒 ${r.unit}</div><input class="unit-price" type="number" min="0" step="0.01" placeholder="CHF"><span class="amount">0.00 CHF</span>`;d.querySelectorAll('input').forEach(x=>x.oninput=()=>recalcCompany());box.appendChild(d)});if(!visible.length)box.innerHTML='<div class="empty-state">Aucune ligne chiffrable n’a été renseignée par Ström pour ce poste.</div>';recalcCompany();show('companyQuote')}
function recalcCompany(){let total=0;$('#companyRows').querySelectorAll('.row').forEach(r=>{const q=num(companyRowQty(r))||0,p=num(r.querySelector('.unit-price').value)||0,v=q*p;total+=v;r.querySelector('.amount').textContent=money(v)});$('#companyTotal').textContent=money(total)}
$('#companyReview').onclick=()=>{let total=0,lines=[];$('#companyRows').querySelectorAll('.row').forEach(r=>{const label=r.querySelector('.designation').textContent,q=companyRowQty(r),u=r.querySelector('.locked-unit').textContent.replace('🔒','').trim(),priceInput=r.querySelector('.unit-price').value,p=num(priceInput),v=(num(q)||0)*(p||0);if(priceInput!=='')total+=v;lines.push(`<tr><td>${label}</td><td>${q} ${u}</td><td>${priceInput===''?'Non renseigné':money(p)}</td><td>${priceInput===''?'—':money(v)}</td></tr>`)});$('#companySummary').innerHTML=`<div class="summary-head"><div><span>Projet</span><strong>${currentProject.address}</strong></div><div><span>Poste</span><strong>${trades[companyTrade].name}</strong></div><div><span>Entreprise</span><strong>${$('#companyName').value||'Non renseigné'}</strong></div></div><table><thead><tr><th>Prestation</th><th>Quantité</th><th>Prix unitaire</th><th>Total</th></tr></thead><tbody>${lines.join('')}</tbody></table><div class="total"><span>Total HT renseigné</span><strong>${money(total)}</strong></div>`;show('companyReviewStep')};
